"use client";

import type { ImageLoaderProps } from "next/image";

// Matching variants are generated by scripts/build-static.mjs before export.
export default function staticImageLoader({ src, width }: ImageLoaderProps) {
  if (!src.startsWith("/") || !/\.(webp|png|jpe?g)$/i.test(src)) return src;
  return `${process.env.NEXT_PUBLIC_BASE_PATH || ""}/responsive${src.replace(/\.(webp|png|jpe?g)$/i, "")}-${width}.webp`;
}
